function stackBar(){const W=400,H=70;const parts=[['Late',K.depLate,'var(--rd)'],['Ships inside 30 days',Math.round(openAll.filter(o=>o.status==='open'&&(o.promised-d0)/864e5<=30).reduce((a,o)=>a+o.v*.5,0)),'var(--am)'],['Not due yet',0,'var(--bl)']];parts[2][1]=K.depV-parts[0][1]-parts[1][1];let x=0,s=`<svg viewBox="0 0 ${W} ${H}">`;parts.forEach(p=>{const w=(W)*p[1]/K.depV;s+=`<rect x="${x}" y="14" width="${Math.max(0,w-2)}" height="22" fill="${p[2]}"><title>${p[0]} · ${moneyFull(p[1])}</title></rect><text x="${x}" y="58" ${DM} font-size="10.5" fill="var(--mu)">${p[0]}</text><text x="${x}" y="10" ${SY} font-size="11" fill="var(--tx)">${money(p[1])}</text>`;x+=w});return s+'</svg>'}
function hist(items,key,buckets,color,unit){const W=400,H=96;const counts=buckets.map(b=>items.filter(i=>i[key]>=b[0]&&i[key]<=b[1]).length);const max=Math.max(...counts);const bw=(W-10)/buckets.length;let s=`<svg viewBox="0 0 ${W} ${H}">`;counts.forEach((c,i)=>{const h=Math.max(2,56*c/max);const x=5+i*bw;const stale=buckets[i][0]>60;s+=`<rect x="${x+3}" y="${64-h}" width="${bw-6}" height="${h}" fill="${stale?color:'var(--line2)'}"><title>${c} ${unit} · ${buckets[i][2]}</title></rect><text x="${x+bw/2}" y="${58-h}" text-anchor="middle" ${SY} font-size="12" fill="${stale?'var(--tx)':'var(--mu)'}">${c}</text><text x="${x+bw/2}" y="82" text-anchor="middle" ${DM} font-size="10" fill="var(--dim)">${buckets[i][2]}</text>`});return s+'</svg>'}
function funnel(){const W=760,H=190;const max=K.pipe[0][1];let s=`<svg viewBox="0 0 ${W} ${H}">`;const cols=K.pipe.length;const cw=W/cols;K.pipe.forEach((p,i)=>{const h=120*p[1]/max;const x=i*cw+8;s+=`<rect x="${x}" y="${150-h}" width="${cw-16}" height="${h}" fill="${i===0?'var(--line2)':i===1?'var(--bl)':i===2?'var(--cy)':i===3?'var(--bl2)':'var(--li)'}" fill-opacity="${i===0?1:.9}"><title>${p[0]} · ${moneyFull(p[1])}</title></rect><text x="${x}" y="${140-h}" ${SY} font-size="17" fill="var(--tx)">${money(p[1])}</text><text x="${x}" y="172" ${DM} font-size="11.5" fill="var(--mu)">${p[0]}</text>`;if(i>0){const leak=K.pipe[i-1][1]-p[1];s+=`<text x="${x-8}" y="${186}" text-anchor="middle" ${DM} font-size="10.5" fill="var(--rd)">${i===1?'never quoted':i===2?'open or lost quotes':i===3?'in production':'on site, not installed'} ${money(leak)}</text>`}});return s+'</svg>'}
function landed(){const W=400,H=170;const max=Math.max(...SHIP.map(s=>s.actual));const bw=W/SHIP.length;let s=`<svg viewBox="0 0 ${W} ${H}">`;SHIP.forEach((sh,i)=>{const x=i*bw;const hq=110*sh.quoted/max,ha=110*sh.actual/max;const over=(sh.actual-sh.quoted)/sh.quoted;const bad=over>=.12;s+=`<rect x="${x+6}" y="${128-hq}" width="${bw/2-7}" height="${hq}" fill="var(--line2)"><title>${sh.id} quoted ${moneyFull(sh.quoted)}</title></rect><rect x="${x+bw/2}" y="${128-ha}" width="${bw/2-7}" height="${ha}" fill="${bad?'var(--rd)':'var(--cy)'}"><title>${sh.id} landed ${moneyFull(sh.actual)} (${Math.round(over*100)}% over)</title></rect><text x="${x+bw/2}" y="${118-ha}" text-anchor="middle" ${SY} font-size="11" fill="${bad?'var(--rd)':'var(--mu)'}">${over>0?'+':''}${Math.round(over*100)}%</text><text x="${x+bw/2}" y="146" text-anchor="middle" ${DM} font-size="9.5" fill="var(--dim)">${sh.origin.replace('High Point','High Pt').replace('Hudson Valley','Hudson').replace('Pennsylvania','Penn.')}</text><text x="${x+bw/2}" y="160" text-anchor="middle" ${DM} font-size="9" fill="var(--dim)">${sh.id.slice(0,4)}</text>`});return s+`<text x="0" y="10" ${DM} font-size="10" fill="var(--dim)">grey quoted, color landed (freight, duties, brokerage)</text></svg>`}
function ranges(){const W=400,H=150;const top=skus.slice().sort((a,b)=>b.spread-a.spread).slice(0,8);let s=`<svg viewBox="0 0 ${W} ${H}">`;top.forEach((k,i)=>{const y=12+i*17;const lo=140+200*(k.low/k.high)*.0+0,x1=140,x2=140+200*(k.spread/K.skuMax);s+=`<text x="0" y="${y+4}" ${DM} font-size="11" fill="var(--mu)">${k.sku}</text><line x1="${x1}" y1="${y}" x2="${x2}" y2="${y}" stroke="${k.spread>=15?'var(--rd)':'var(--am)'}" stroke-width="3"/><circle cx="${x1}" cy="${y}" r="3" fill="var(--tx)"/><circle cx="${x2}" cy="${y}" r="3" fill="var(--tx)"/><text x="${x2+8}" y="${y+4}" ${SY} font-size="11" fill="var(--tx)">${k.spread}%</text><title>${k.sku} · ${moneyFull(k.low)} to ${moneyFull(k.high)} across three reps</title>`});return s+`<text x="0" y="${H-2}" ${DM} font-size="10" fill="var(--dim)">lowest to highest price quoted for the same item, three reps</text></svg>`}
function hitBars(){const top=byFirm.filter(f=>f.hit!==null&&f.won+f.lost>=3).sort((a,b)=>b.hit-a.hit).slice(0,6);return `<table class="tbl">${top.map(f=>`<tr data-firm="${f.i}"><td style="width:48%">${esc(f.n)}</td><td><div class="bar"><i style="width:${f.hit}%;background:${f.hit<40?'var(--rd)':f.hit<65?'var(--am)':'var(--cy)'}"></i></div></td><td class="n" style="width:50px">${f.hit}%</td></tr>`).join('')}</table>`}
/* ---------- ledger ---------- */
const GLOSS={'deposit exposure':'Client money you are holding on orders you have not finished. If an order slips, this is what you may have to explain or refund.','landed cost':'What a shipment really cost once freight, duties and brokerage are added to the maker price. The quote usually only has the maker price.','imputed':'A blank we filled with a statistically defended value. Always flagged so you know which numbers are measured and which are modeled.','confidence':'How sure we are about the numbers on this screen, stated as a percentage before you look at a chart. 95% means one number in twenty may move when the missing record turns up.','hit rate':'Won quotes divided by decided quotes. Open quotes do not count until they are won or lost.','promised ship date':'The date you told the client. Not the date production thinks it is.','price book':'One list of what each item sells for to each kind of customer. When three reps carry three lists you have no price book.','spec':'A designer wrote your product into a hotel project. It is not a quote, not an order, and most of them never become one.','memo':'A sample or piece out with a designer on approval. Yours until it comes back, which many never do.'};
function g(t){const k=t.toLowerCase();return `<span class="gl" data-g="${esc(k)}">${t}</span>`}
const TILES=()=>[
 {id:'late',c:'c4',t:'Orders past promised ship',kpi:K.lateN,sub:`<b>${money(K.lateV)}</b> of ${T.unit}, average <b>${K.lateAvg} days</b> past the ${g('promised ship date')}`,chart:dotStrip(),
  what:`${K.lateN} open orders have gone past the ship date someone wrote on the acknowledgement. Together they are worth ${moneyFull(K.lateV)}. The oldest is ${LATE[0]} days late.`,why:`The promised date lives in QuickBooks and the production schedule lives in a workshop spreadsheet. The two never meet, so nobody sees a slip until the designer calls. 4 of these 14 had no promised date in any file at all; we filled them from lead times on similar orders and flagged them.`,monday:['Call the four designers on the orders over 28 days before they call you. Offer a date you can keep.','Put the promised date on the production board, not just the invoice.','Have the bookkeeper export open orders every Friday. The ledger refreshes from that one file.'],worth:[money(K.lateV),'of revenue sitting past date, plus the next three projects each of those firms will spec'],rows:late.slice(0,6).map(o=>[`${o.id} · ${FIRMS[o.f]} · ${HOTELS[o.h].split(',')[0]}`,`${o.daysLate}d · ${money(o.v)}`])},
 {id:'dep',c:'c4',t:'Deposit exposure',kpi:money(K.depV),sub:`held on <b>${K.openN}</b> open orders · <b>${money(K.depLate)}</b> of it on orders already late`,chart:stackBar(),
  what:`You are holding ${moneyFull(K.depV)} of client money against work that is not finished. ${moneyFull(K.depLate)} of that is on orders that are already past their promised date. This is the ${g('deposit exposure')} number.`,why:`Deposits are posted as income in QuickBooks the day they arrive, so the books look healthy while the obligation grows. Nobody has one list of what has been collected against what has been delivered.`,monday:['Split deposits from earned revenue in the books. Your accountant can do it in an afternoon.','Rank the late orders by deposit held. The designer holding the most money gets the first call.','Set a rule: no deposit on a custom order without a promised date on the acknowledgement.'],worth:[money(K.depLate),'of client money at risk of refund requests or make goods on late orders'],rows:late.slice().sort((a,b)=>b.v-a.v).slice(0,6).map(o=>[`${o.id} · ${FIRMS[o.f]}`,`deposit ${money(o.v*.5)}`])},
 {id:'quotes',c:'c4',t:'Quotes out over 60 days',kpi:K.qStale.length,sub:`<b>${money(K.qStaleV)}</b> quoted, no yes, no no · ${K.qOpen.length-K.qStale.length} more inside 60 days`,chart:hist(K.qOpen,'age',[[0,30,'0 to 30d'],[31,60,'31 to 60d'],[61,90,'61 to 90d'],[91,120,'91 to 120d'],[121,400,'over 120d']],'var(--am)','quotes'),
  what:`${K.qStale.length} quotes worth ${moneyFull(K.qStaleV)} were sent more than 60 days ago and nobody has written down what happened. Some were lost to a competitor, some were value engineered out, some the designer is still waiting on the owner for.`,why:`The quote log records when a quote went out. It does not record what happened next, because the answer comes by phone or shows up as a PO weeks later. So every quote looks open forever.`,monday:['Call the ten largest. Ask one question: is this project still alive. Write the answer in the log.','Add a status column with four words only: open, won, lost, dead.','Stop quoting new work for a firm that has three quotes over 90 days with no answer until you have talked.'],worth:[money(K.qStaleV*.22),'if you convert one in five at your current '+K.hit+'% '+g('hit rate')],rows:K.qStale.slice().sort((a,b)=>b.v-a.v).slice(0,6).map(q=>[`${q.id} · ${FIRMS[q.f]} · ${HOTELS[q.h].split(',')[0]}`,`${q.age}d · ${money(q.v)}`])},
 {id:'pipe',c:'c7',t:'From spec to installed',kpi:money(K.pipe[0][1]),sub:`${g('spec')}'d into hotel projects · <b>${money(K.pipe[4][1])}</b> actually installed and paid · ${K.hit}% ${g('hit rate')} on decided quotes`,chart:funnel(),
  what:`Everything a designer has written your product into, followed to the end. ${moneyFull(K.pipe[0][1])} specified, ${moneyFull(K.pipe[1][1])} quoted, ${moneyFull(K.pipe[2][1])} on order, ${moneyFull(K.pipe[4][1])} installed. The red numbers under each step are where dollars leak.`,why:`Specs, quotes, orders and shipments live in four different files owned by four different people. Nobody has ever laid them end to end, so the leak between quoted and ordered has never been measured.`,monday:['Pick the largest leak. For most makers it is quoted to ordered. Call every open quote on a project that has already ordered something else from you.','Track the designer who specifies you, not just the purchasing agent who sends the PO. They are often different firms.','Review this funnel once a month with whoever runs the showroom. Ten minutes.'],worth:[money(K.pipe[1][1]-K.pipe[2][1]),'quoted but not ordered. Winning one more in ten changes the year.'],rows:K.pipe.map(p=>[p[0],moneyFull(p[1])])},
 {id:'landed',c:'c5',t:'Landed cost against quote',kpi:K.shipOver.length+' of '+SHIP.length,sub:`shipments landed <b>12% or more</b> over the price you quoted on · <b>${money(K.shipDelta)}</b> total gap this year`,chart:landed(),
  what:`${g('Landed cost')} is the maker price plus freight, duties and brokerage. On ${K.shipOver.length} of ${SHIP.length} containers this year it came in more than 12% above what the quote assumed, and the quote had already gone to the client.`,why:`The broker invoice arrives six weeks after the quote and goes to the bookkeeper. The person writing quotes never sees it, so the freight assumption in the quote template has not changed since it was built.`,monday:['Update the freight and duty assumption in the quote template with this year\'s real average.','Require the container number on every maker invoice so the broker bill can be matched automatically.','Quote big custom orders with a freight line that floats, not a flat percent.'],worth:[money(K.shipDelta),'absorbed into margin this year without a decision being made'],rows:SHIP.slice().sort((a,b)=>(b.actual/b.quoted)-(a.actual/a.quoted)).slice(0,5).map(s=>[`${s.id} · ${s.origin}`,`+${Math.round(100*(s.actual-s.quoted)/s.quoted)}% · ${money(s.actual-s.quoted)}`])},
 {id:'samples',c:'c4',t:T.sample.charAt(0).toUpperCase()+T.sample.slice(1)+' out over 60 days',kpi:K.sStale.length,sub:`<b>${money(K.sStaleV)}</b> of ${T.sample} out on ${g('memo')} with no return on file`,chart:hist(samples,'age',[[0,30,'0 to 30d'],[31,60,'31 to 60d'],[61,120,'61 to 120d'],[121,180,'121 to 180d'],[181,400,'over 180d']],'var(--or)',T.sample),
  what:`${K.sStale.length} ${T.sample} have been out with designers for more than 60 days with no return logged. That is ${moneyFull(K.sStaleV)} of inventory you paid for, sitting in other people's libraries.`,why:`Three reps share one sheet and each one fills in the Returned column a different way. Yes, yes?, still out, blank. Nobody owns the chase because nobody can see the total.`,monday:['Send one email to every firm holding more than $1,000 of samples: keep it and we invoice, or send it back, your call.','One Returned column, two values: date or blank.','Price the sample program. If it costs $38K a year, the firms that never order should pay for theirs.'],worth:[money(K.sStaleV),'of samples to recover or bill, every year'],rows:byFirm.filter(f=>f.samples).sort((a,b)=>b.sampV-a.sampV).slice(0,6).map(f=>[f.n,`${f.samples} out · ${money(f.sampV)}`])},
 {id:'price',c:'c4',t:'One price book',kpi:skus.length,sub:`items quoted at <b>three different prices</b> by three reps · worst spread <b>${K.skuMax}%</b>`,chart:ranges(),
  what:`${skus.length} items were quoted at materially different prices to similar customers in the same quarter. The worst spread is ${K.skuMax}%. Designers compare notes. This is how you lose a firm without ever hearing why.`,why:`Each rep keeps a price sheet from the year they started. Discounts get negotiated per project and never written back. There is no single ${g('price book')}.`,monday:['Publish one price list and one discount schedule. Trade, hospitality volume, dealer. Three columns.','Any quote below the schedule needs the owner\'s initials. One line on the form.','Re-quote the two open projects that received the lowest price before they become the new normal.'],worth:[money(skus.reduce((a,k)=>a+(k.high-k.low),0)*18),'of margin given away per year at current volume, before a single lost customer'],rows:skus.slice().sort((a,b)=>b.spread-a.spread).slice(0,6).map(k=>[`${k.sku} · ${T.items[k.it]}`,`${moneyFull(k.low)} to ${moneyFull(k.high)}`])},
 {id:'hit',c:'c4',t:'Hit rate by firm',kpi:K.hit+'%',sub:`won on decided quotes · the firms below each have two or more decisions this year`,chart:hitBars(),
  what:`Your overall ${g('hit rate')} is ${K.hit}%. Underneath that average are firms that order almost everything they ask about and firms that have never once said yes.`,why:`Nobody has ever counted. Reps remember the wins. The quote log remembers everything but has no outcome column.`,monday:['Spend sample and showroom time on the firms above 65%.','Ask the firms under 40% one honest question: what would it take.','Stop sending samples to a firm with zero wins in two years unless the owner approves.'],worth:['2 to 4 hours','a week of rep time redirected to firms that actually buy'],rows:byFirm.filter(f=>f.hit!==null).sort((a,b)=>b.hit-a.hit).slice(0,6).map(f=>[f.n,`${f.hit}% · ${f.won} won, ${f.lost} lost`])}
];
function ledger(){const tiles=TILES();$('#confstrip').innerHTML=`<div class="big num">95%</div><div class="k">${g('confidence')} · <b>1,284</b> rows in · <b>1,187</b> clean rows out · <b>97</b> duplicates listed · <b>118</b> values ${g('imputed')} and flagged</div><div class="sig"><span>Validated <b>J. Martinko, COO</b></span><span>Security <b>J. Boynton, CIO</b></span><span>Statistics <b>L. Marinucci</b></span><span>Showing <b>${T.label}</b></span></div>`;
 $('#grid').innerHTML=tiles.map(t=>`<div class="tile ${t.c}" data-id="${t.id}"><div class="th"><div class="tt">${t.t}</div><span class="fix">Fix</span></div><div class="kpi">${t.kpi}</div><div class="sub">${t.sub}</div>${t.chart}</div>`).join('')+firmTable();
 $('#grid').onclick=e=>{const tr=e.target.closest('tr[data-firm]');if(tr){openFirm(+tr.dataset.firm);return}const tile=e.target.closest('.tile');if(!tile)return;const t=tiles.find(x=>x.id===tile.dataset.id);if(t)openTile(t)};
 $('#confstrip').onclick=()=>openDrawer(`<div class="eyebrow">HOW WE GOT TO 95%</div><div class="kpi">95%</div><p>Four files, 1,284 rows. We standardized 312 customer spellings to 41 firms, listed and removed 97 duplicate rows, linked 1,187 rows on one key per order, and filled 118 blanks.</p><h3>What imputed means here</h3><p>A blank promised ship date, a missing deposit, a duty line that said see attached. Each was filled using the pattern in your own records, under a method Lawrence Marinucci has used for 30 years in clinical trials, where a wrong fill gets a drug rejected. Every filled value carries a flag and a confidence, so you always know which numbers were measured and which were modeled.</p><h3>Who signed</h3><p>Jacob M. Martinko traced every KPI on this screen back to source rows and signed the validation workbook. Justin M. Boynton reviewed where the files sit and who can see them. Nothing is published to you without both.</p><h3>What 95% means on Monday</h3><p>About one number in twenty may move when the missing record turns up. We tell you which twenty.</p>`)}
function firmTable(){const rows=byFirm.slice(0,12);return `<div class="tile c12" data-id="firms" style="cursor:default"><div class="th"><div class="tt">By firm · open orders, late, quotes waiting, samples out</div><span class="fix">Tap a row</span></div><div class="tblwrap"><table class="tbl"><thead><tr><th>Firm</th><th class="n" style="text-align:right">Open orders</th><th class="n" style="text-align:right">Late</th><th class="n hidem" style="text-align:right">Quotes open</th><th class="n hidem" style="text-align:right">Hit rate</th><th class="n hidem" style="text-align:right">Samples out</th><th style="padding-left:14px">Read</th></tr></thead><tbody>${rows.map(f=>`<tr data-firm="${f.i}"><td>${esc(f.n)}</td><td class="n">${money(f.openV)}</td><td class="n ${f.lateN?'rd':''}">${f.lateN||'·'}</td><td class="n hidem">${f.qOpen?money(f.qOpenV):'·'}</td><td class="n hidem">${f.hit===null?'·':f.hit+'%'}</td><td class="n hidem ${f.samples>3?'am':''}">${f.samples||'·'}</td><td class="mu" style="font-size:12.5px;padding-left:14px;white-space:nowrap">${read(f)}</td></tr>`).join('')}</tbody></table></div></div>`}
function read(f){if(f.lateN>=2)return 'Call before they call you';if(f.qOpenV>80000&&f.hit!==null&&f.hit>=60)return 'Buyer with money waiting';if(f.hit!==null&&f.hit<35)return 'Asks, rarely buys';if(f.samples>3)return 'Holding your samples';if(f.lateN===1)return 'One late order, fix it this week';return 'Healthy'}
function openTile(t){openDrawer(`<div class="eyebrow">${t.t}</div><div class="kpi">${t.kpi}</div><p class="mu" style="font-size:14px">${t.sub}</p><h3>What this is</h3><p>${t.what}</p><h3>Why it is happening</h3><p>${t.why}</p><h3>What to do Monday</h3><ol>${t.monday.map(m=>`<li>${m}</li>`).join('')}</ol><h3>The rows behind it</h3><div class="rows">${t.rows.map(r=>`<div><span>${esc(r[0])}</span><b>${esc(r[1])}</b></div>`).join('')}</div><div class="worth"><b>${t.worth[0]}</b><span class="mu">${t.worth[1]}</span></div>`)}
function openFirm(i){const f=byFirm.find(x=>x.i===i);const o=openAll.filter(x=>x.f===i),l=late.filter(x=>x.f===i),q=quotes.filter(x=>x.f===i&&x.status==='open'),s=samples.filter(x=>x.f===i&&x.age>60);
 openDrawer(`<div class="eyebrow">FIRM</div><div class="kpi" style="font-size:30px">${esc(f.n)}</div><p class="mu">${read(f)}</p><h3>Open with them</h3><p>${f.lateN?`You owe them ${l.length} late order${l.length>1?'s':''} worth ${money(f.lateV)}. Lead with a date you can keep, then ask about the ${q.length} open quote${q.length===1?'':'s'}.`:q.length?`They have ${money(f.qOpenV)} quoted and waiting. Ask which projects are still alive.`:s.length?`They are holding ${s.length} ${T.sample} worth ${money(f.sampV)}. Ask if they want to keep them or send them back.`:'Nothing urgent. Ask what they are specifying next quarter.'}</p><h3>Open orders</h3><div class="rows">${o.length?o.map(x=>`<div><span>${x.id} · ${T.items[x.it]} · ${HOTELS[x.h].split(',')[0]}</span><b class="${x.status==='late'?'rd':''}">${x.status==='late'?x.daysLate+'d late':'ships '+iso(x.promised)}</b></div>`).join(''):'<div><span>None</span><b></b></div>'}</div><h3>Quotes open</h3><div class="rows">${q.length?q.map(x=>`<div><span>${x.id} · ${HOTELS[x.h]}</span><b class="${x.age>60?'am':''}">${x.age}d · ${money(x.v)}</b></div>`).join(''):'<div><span>None</span><b></b></div>'}</div><h3>${T.sample.charAt(0).toUpperCase()+T.sample.slice(1)} out over 60 days</h3><div class="rows">${s.length?s.map(x=>`<div><span>${T.items[x.it]} · ${x.rep}</span><b>${x.age}d · ${moneyFull(x.v)}</b></div>`).join(''):'<div><span>None</span><b></b></div>'}</div>`)}
function openDrawer(html){$('#drawer').innerHTML=`<button class="x" aria-label="Close">×</button>${html}`;$('#drawer').classList.add('on');$('#veil').classList.add('on');$('#drawer').scrollTop=0}
function closeDrawer(){$('#drawer').classList.remove('on');$('#veil').classList.remove('on')}
/* ---------- glossary tip ---------- */
const tip=$('#tip');let tipOn=null;
function showTip(el){const k=el.dataset.g;if(!GLOSS[k])return;tip.innerHTML=`<b style="font-family:var(--syne);font-size:12px;letter-spacing:.1em;text-transform:uppercase;color:var(--cy)">${esc(k)}</b><br>${GLOSS[k]}`;tip.classList.add('on');const r=el.getBoundingClientRect();const w=Math.min(280,window.innerWidth-20);let x=r.left,y=r.bottom+8;if(x+w>window.innerWidth-10)x=window.innerWidth-10-w;if(y+140>window.innerHeight)y=r.top-8-tip.offsetHeight;tip.style.left=x+'px';tip.style.top=y+'px';tipOn=el}
document.addEventListener('mouseover',e=>{const el=e.target.closest('.gl');if(el)showTip(el);else if(tipOn&&!e.target.closest('#tip')){tip.classList.remove('on');tipOn=null}});
document.addEventListener('click',e=>{const el=e.target.closest('.gl');if(el){e.stopPropagation();showTip(el);return}if(e.target.closest('#drawer .x')||e.target.id==='veil')closeDrawer()},true);
document.addEventListener('keydown',e=>{if(e.key==='Escape')closeDrawer()});

/* ---------- beyond monday ---------- */
const WEEKS=13;let SCA='base';
const NEWBUY=[['Corbel & Vane','Ideal','Specifies your category on two open hotel projects. Never asked you for a quote.'],['Studio Ferrante','Ideal','Lead designer on a 140 key boutique in Charleston. Buys through a purchasing agent you already know.'],['Marrow Lane Interiors','Strong','Residential and small hospitality. Posted three installs this year in your category.'],['Okonkwo Design Office','Strong','New firm, ex Rockwell. Spec sheets public on two projects.'],['Halstead Purchasing','Strong','Purchasing agent for three owners you have never sold to.'],['Bellweather Hospitality','Watch','Big projects, long cycles, buys on price.'],['Tolan + Reyes','Watch','Spec work mostly value engineered out at bid.'],['Ashworth Procurement','Watch','Rebids everything. Low hit rate for everyone.'],['Linden Street Studio','Strong','Two installs in your category this year, both sourced overseas.']];
function fcModel(){const rows=K.qOpen.map(q=>{const f=byFirm.find(x=>x.i===q.f);const hit=(f&&f.hit!==null)?f.hit/100:K.hit/100;const p=Math.max(.03,Math.min(.92,hit*Math.exp(-q.age/140)*1.15));const wk=Math.min(WEEKS,Math.max(1,Math.round(1+q.age/30+(1-p)*5)));return{q,f:FIRMS[q.f],p,wk,ev:q.v*p}});
 const cum=[];let e=0,v=0;for(let w=1;w<=WEEKS;w++){rows.filter(r=>r.wk===w).forEach(r=>{e+=r.ev;v+=r.p*(1-r.p)*r.q.v*r.q.v});cum.push({w,e,lo:Math.max(0,e-1.28*Math.sqrt(v)),hi:e+1.28*Math.sqrt(v)})}
 const risk=late.map(o=>({o,p:Math.min(.65,.08+o.daysLate/90)})).sort((a,b)=>b.p-a.p);const last=cum[WEEKS-1];
 return{rows:rows.sort((a,b)=>b.ev-a.ev),cum,risk,E:e,lo:last.lo,hi:last.hi,atRisk:risk.reduce((a,r)=>a+r.p*r.o.v,0),likely:rows.filter(r=>r.p>=.5).length}}
function fanChart(m){const W=760,H=210,L=34,R=16,T0=14,B=34;const max=m.hi*1.05;const X=w=>L+(w-1)/(WEEKS-1)*(W-L-R);const Y=v=>T0+(H-T0-B)*(1-v/max);
 let s=`<svg class="fan" viewBox="0 0 ${W} ${H}">`;[0,.25,.5,.75,1].forEach(f=>{const y=Y(max*f);s+=`<line x1="${L}" y1="${y}" x2="${W-R}" y2="${y}" stroke="var(--line)"/><text x="${L-6}" y="${y+3}" text-anchor="end" ${DM} font-size="10" fill="var(--dim)">${money(max*f)}</text>`});
 const up=m.cum.map(c=>`${X(c.w)},${Y(c.hi)}`),dn=m.cum.slice().reverse().map(c=>`${X(c.w)},${Y(c.lo)}`);s+=`<polygon points="${up.concat(dn).join(' ')}" fill="var(--cy)" fill-opacity=".14"/>`;
 s+=`<polyline points="${m.cum.map(c=>`${X(c.w)},${Y(c.e)}`).join(' ')}" fill="none" stroke="var(--cy)" stroke-width="2"/>`;
 m.cum.forEach(c=>{if(c.w%2===1)s+=`<text x="${X(c.w)}" y="${H-12}" text-anchor="middle" ${DM} font-size="10" fill="var(--dim)">${dAdd(d0,7*c.w).toLocaleDateString('en-US',{month:'short',day:'numeric'})}</text>`;s+=`<circle cx="${X(c.w)}" cy="${Y(c.e)}" r="3" fill="var(--cy)"><title>Week ${c.w} · expected ${moneyFull(c.e)} · 80% range ${moneyFull(c.lo)} to ${moneyFull(c.hi)}</title></circle>`});
 s+=`<text x="${X(WEEKS)}" y="${Y(m.hi)-6}" text-anchor="end" ${DM} font-size="10" fill="var(--mu)">high ${money(m.hi)}</text><text x="${X(WEEKS)}" y="${Y(m.lo)+14}" text-anchor="end" ${DM} font-size="10" fill="var(--mu)">low ${money(m.lo)}</text>`;
 return s+`<text x="${L}" y="10" ${DM} font-size="10" fill="var(--dim)">expected bookings from today's open quotes, cumulative by week, shaded band is the 80% range</text></svg>`}
const SC=()=>({best:{k:'Best',late:K.lateN-2,dep:Math.round(K.depLate*.86/1000)*1000,gap:Math.round(K.shipDelta*.78/1000)*1000,stale:K.qStale.length-5,note:'Every blank promised date is still in the future. Blank deposits are the 50% the contract says. Blank duty lines match the broker average.'},
 base:{k:'Base',late:K.lateN,dep:K.depLate,gap:K.shipDelta,stale:K.qStale.length,note:'What the ledger above shows. Every blank filled with the most likely value from your own history, and flagged.'},
 worst:{k:'Worst',late:K.lateN+4,dep:Math.round(K.depLate*1.18/1000)*1000,gap:Math.round(K.shipDelta*1.31/1000)*1000,stale:K.qStale.length+6,note:'Every blank promised date has already passed. Blank deposits were collected in full. Blank duty lines land like the worst container this year.'}});
function scTable(sc){const rows=[['Orders past promised ship',x=>x.late],['Deposit on late orders',x=>money(x.dep)],['Landed over quote this year',x=>money(x.gap)],['Quotes stale past 60 days',x=>x.stale]];
 return `<div class="sctabs">${['best','base','worst'].map(k=>`<button type="button" class="sctab ${SCA===k?'on':''}" data-sc="${k}">${sc[k].k}</button>`).join('')}</div><table class="sctbl"><thead><tr><th></th>${['best','base','worst'].map(k=>`<th>${sc[k].k}</th>`).join('')}</tr></thead><tbody>${rows.map(r=>`<tr><td>${r[0]}</td>${['best','base','worst'].map(k=>`<td class="${SCA===k?'on':''}">${r[1](sc[k])}</td>`).join('')}</tr>`).join('')}</tbody></table><p class="mu" style="font-size:12.5px;margin-top:10px">${sc[SCA].note}</p>`}
const WATCH=[['+2','orders slipped past promised ship this week','PO-1203 Northlight Interiors, PO-1151 Castellan Design. Both had a date in production that never reached QuickBooks.','rd'],['Won','Q-2231 closed at $41K. The forecast had it at 71%.','Sutton Rowe Design. Deposit invoice went out the same morning.','ok'],['+9%','TGHU 902 7716 landed over quote, inside the 12% line','Freight up, duties flat. Quote template freight assumption still holds.','am'],['3','fabric memos returned by Avery Lane Studio','58 still out past 60 days. Chase list refreshed.','mu'],['96%','confidence, up from 95%','11 new blanks filled from new rows. 2 values you corrected by hand replaced ours and retrained the fill.','li']];
function watchList(){return `<div class="watch">${WATCH.map(w=>`<div><b class="${w[3]}">${w[0]}</b><span>${w[1]}<small>${w[2]}</small></span></div>`).join('')}</div>`}
function gradeFirm(f){if(f.hit!==null&&f.hit>=60&&f.qOpenV>40000)return'Ideal';if(f.openN>=2||(f.hit!==null&&f.hit>=50))return'Strong';if(f.hit!==null&&f.hit<35)return'Watch';return'Watch'}
function radarList(){const cur=byFirm.map(f=>({n:f.n,g:gradeFirm(f),note:read(f),cur:true}));const neu=NEWBUY.map(x=>({n:x[0],g:x[1],note:x[2],cur:false}));const all=cur.concat(neu);const cnt=g=>all.filter(x=>x.g===g).length;
 const show=neu.slice(0,3).concat(cur.filter(x=>x.g==='Ideal').slice(0,2),cur.filter(x=>x.g==='Strong').slice(0,1));
 return{all,cnt,html:`<div class="rad">${show.map(x=>`<div><span>${esc(x.n)}${x.cur?'':'<span class="new">never quoted</span>'}<small>${esc(x.note)}</small></span><span class="pill ${x.g}">${x.g}</span></div>`).join('')}</div>`}}
const BEYOND=()=>{const m=fcModel();const sc=SC();const rl=radarList();return[
 {id:'fc',c:'c7',t:'90 day forecast',kpi:money(m.E),sub:`expected to book from today's open quotes · 80% range <b>${money(m.lo)}</b> to <b>${money(m.hi)}</b> · <b>${m.likely}</b> quotes better than even odds · <b>${money(m.atRisk)}</b> of late orders at risk of cancelling`,chart:fanChart(m),
  what:`Each open quote gets a probability of closing from your own history: how often that firm says yes, how old the quote is, how big it is. Added up week by week, that is the money you can expect to book, with an honest range around it. The same method gives every late order a probability of being cancelled.`,why:`A quote log tells you what went out. It cannot tell you what is coming back. With the outcomes cleaned and linked, the pattern in your own records does, and the range is stated so nobody mistakes a forecast for a promise.`,
  monday:[`Call the ${m.rows.filter(r=>r.p>=.5).length} quotes better than even odds first. They are closest to money.`,`The ${m.risk.filter(r=>r.p>=.4).length} late orders with a cancel risk over 40% get a new date and a phone call this week.`,'Plan production and cash on the low end of the range, not the middle.'],
  rows:m.rows.slice(0,6).map(r=>[`${r.q.id} · ${r.f}`,`${moneyFull(r.q.v)} · ${Math.round(r.p*100)}% · week ${r.wk}`]),worth:[money(m.E),'expected bookings over 13 weeks, refreshed every Monday from your files']},
 {id:'sc',c:'c5',t:'Best, base, worst',kpi:money(sc[SCA].dep),sub:`deposit exposure on late orders in the <b>${sc[SCA].k}</b> case · <b>118</b> filled blanks pushed to either end · tap a case`,chart:scTable(sc),
  what:`Every blank we filled has a range, not just a best guess. The best case pushes each one the way you would hope. The worst case pushes each one the way you fear. The base case is what the ledger shows. Four numbers move: late orders, deposit on late orders, landed cost over quote, and stale quotes.`,why:`A blank promised ship date could be next month or last month. A blank deposit could be zero or paid in full. Pretending the base case is certain is how small businesses get surprised. Showing the ends is how you plan.`,
  monday:['Run cash on the worst case for the next 60 days. If it still works, sleep.','Chase the blanks that swing the most. Four promised dates account for most of the gap between best and worst.','Ask us for the scenario you actually worry about. It is one line to add.'],
  rows:[['Promised ship, 4 blanks','best: all future · worst: all past'],['Deposits, 9 blanks','best: 50% collected · worst: 100% collected'],['Duty lines, 6 blanks','best: broker average · worst: worst container'],['Quote outcomes, 11 blanks','best: still alive · worst: lost']],worth:[money(sc.worst.dep-sc.best.dep),'swing in deposit exposure between best and worst. That is what the blanks are hiding.']},
 {id:'wk',c:'c6',t:'Weekly watch',kpi:'Every Monday',sub:`by 8 am · you export, we run, Jake signs what changed · this is the list for <b>Monday, November 16</b>`,chart:watchList(),
  what:`Azorian3 is not a cleanup you buy once. Every Monday the same four exports go in, the ledger refreshes, and you get the five changes that matter: what slipped, what closed, what landed over, what came back, and how the confidence moved.`,why:`Numbers rot. A ledger that was right in November is wrong by January unless someone keeps it right. We do, and a person signs the diff every week so you never wonder whether to trust it.`,
  monday:['Read the five lines. Two minutes.','Forward the slipped orders to whoever owns the workshop schedule.','Correct anything we filled wrong. Your correction retrains the fill for next week.'],
  rows:WATCH.map(w=>[w[1],w[0]]),worth:['5 lines','every Monday, signed. The whole product in two minutes a week.']},
 {id:'rad',c:'c6',t:'Buyers in your market',kpi:rl.all.length,sub:`designers and purchasing agents in your market, graded · <b>${rl.cnt('Ideal')}</b> ideal · <b>${rl.cnt('Strong')}</b> strong · <b>${NEWBUY.length}</b> have never asked you for a quote`,chart:rl.html,
  what:`The same radar we use to walk a trade show floor, pointed at your market. Every firm in your quote log is graded on how it actually buys from you. Then we add the firms that specify your category on public projects and have never once called you, with a reason to walk in.`,why:`Your best next customer is probably specifying a competitor this month. Nobody in a 20 person company has time to read hotel pipelines and spec sheets. We do, and we hand you a graded list with an opener for each.`,
  monday:[`Walk into the ${rl.cnt('Ideal')} ideal firms this month. Lead with the project they are already on.`,'Stop sending samples to the firms graded Watch until they say yes once.','Give the list to whoever does your showroom follow up. One page, graded, with openers.'],
  rows:NEWBUY.slice(0,6).map(x=>[x[0],x[1]]),worth:[NEWBUY.length+' firms','in your market specifying your category who have never asked you for a quote. We walk the floor the same way.']}
]};
function beyond(){const tiles=BEYOND();const el=$('#bgrid');if(!el)return;el.innerHTML=tiles.map(t=>`<div class="tile ${t.c}" data-id="${t.id}"><div class="th"><div class="tt">${t.t}</div><span class="fix">Explain</span></div><div class="kpi">${t.kpi}</div><div class="sub">${t.sub}</div>${t.chart}</div>`).join('');
 el.onclick=e=>{const tb=e.target.closest('.sctab');if(tb){SCA=tb.dataset.sc;beyond();return}const tile=e.target.closest('.tile');if(!tile)return;const t=tiles.find(x=>x.id===tile.dataset.id);if(t)openTile(t)}}
